import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"24、【復】 震下坤上","description":"溫公易說 - 24、【復】 震下坤上","frontmatter":{"title":"24、【復】 震下坤上","description":"溫公易說 - 24、【復】 震下坤上"},"headers":[],"relativePath":"classics/wengong/025.md","filePath":"classics/wengong/025.md"}'),l={name:"classics/wengong/025.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_24、【復】-震下坤上" tabindex="-1">24、【復】 震下坤上 <a class="header-anchor" href="#_24、【復】-震下坤上" aria-label="Permalink to “24、【復】 震下坤上”">​</a></h1><h3 id="彖曰-復-亨。剛反動而以順行-是以出入無疾-朋來無咎。反覆其道-七日來複-天行也。利有攸往-剛長也。復其見天地之心乎" tabindex="-1">彖曰：復，亨。剛反動而以順行，是以出入無疾，朋來無咎。反覆其道，七日來複，天行也。利有攸往，剛長也。復其見天地之心乎？ <a class="header-anchor" href="#彖曰-復-亨。剛反動而以順行-是以出入無疾-朋來無咎。反覆其道-七日來複-天行也。利有攸往-剛長也。復其見天地之心乎" aria-label="Permalink to “彖曰：復，亨。剛反動而以順行，是以出入無疾，朋來無咎。反覆其道，七日來複，天行也。利有攸往，剛長也。復其見天地之心乎？”">​</a></h3><p>七日來複何也？冬至卦氣起於中孚，次復，次屯，次謙，次睽。凡一卦御六日，二百四十分日之二十一，五卦合三十日，二百四十分日之一百五。此冬至距大寒之數也，故入冬至，凡涉七日而復之氣應也。</p><h3 id="象曰-雷在地中-復。先王以至日閉關-商旅不行-後不省方。" tabindex="-1">象曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。 <a class="header-anchor" href="#象曰-雷在地中-復。先王以至日閉關-商旅不行-後不省方。" aria-label="Permalink to “象曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。”">​</a></h3><h3 id="初九-不遠復-無祗悔-元吉-象曰-不遠之復-以修身也。" tabindex="-1">初九：不遠復，無祗悔，元吉 象曰：不遠之復，以修身也。 <a class="header-anchor" href="#初九-不遠復-無祗悔-元吉-象曰-不遠之復-以修身也。" aria-label="Permalink to “初九：不遠復，無祗悔，元吉 象曰：不遠之復，以修身也。”">​</a></h3><h3 id="六二-休復-吉-象曰-休復之吉-以下仁也。" tabindex="-1">六二：休復，吉 象曰：休復之吉，以下仁也。 <a class="header-anchor" href="#六二-休復-吉-象曰-休復之吉-以下仁也。" aria-label="Permalink to “六二：休復，吉 象曰：休復之吉，以下仁也。”">​</a></h3><h3 id="六三-頻復-厲-無咎-象曰-頻復之厲-義無咎也。" tabindex="-1">六三：頻復，厲，無咎 象曰：頻復之厲，義無咎也。 <a class="header-anchor" href="#六三-頻復-厲-無咎-象曰-頻復之厲-義無咎也。" aria-label="Permalink to “六三：頻復，厲，無咎 象曰：頻復之厲，義無咎也。”">​</a></h3><p>復者，過而能復之謂也。不慎其始，頻過而復，亦已危矣。雖然，猶愈於迷而不復也，故曰無咎。</p><h3 id="六四-中行獨復-象曰-中行獨復-以從道也。" tabindex="-1">六四：中行獨復 象曰：中行獨復，以從道也。 <a class="header-anchor" href="#六四-中行獨復-象曰-中行獨復-以從道也。" aria-label="Permalink to “六四：中行獨復 象曰：中行獨復，以從道也。”">​</a></h3><p>中行者，行於眾陰之中也。四行眾陰之中，獨能履正思順，下應於陽，不陷溺於群邪，而能自復於善者也。故曰中行獨復。孔子曰：不曰堅乎，磨而不磷？不曰白乎，涅而不淄？此之謂也。</p><h3 id="六五-敦復-無悔-象曰-敦復無悔-中以自考也。" tabindex="-1">六五：敦復，無悔 象曰：敦復無悔，中以自考也。 <a class="header-anchor" href="#六五-敦復-無悔-象曰-敦復無悔-中以自考也。" aria-label="Permalink to “六五：敦復，無悔 象曰：敦復無悔，中以自考也。”">​</a></h3><h3 id="上六-迷復-兇-有災眚。用行師-終有大敗-以其國君兇-至於十年不克徵-象曰-迷復之兇-反君道也。" tabindex="-1">上六：迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵 象曰：迷復之兇，反君道也。 <a class="header-anchor" href="#上六-迷復-兇-有災眚。用行師-終有大敗-以其國君兇-至於十年不克徵-象曰-迷復之兇-反君道也。" aria-label="Permalink to “上六：迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵 象曰：迷復之兇，反君道也。”">​</a></h3>',12)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
